module tb;
    // Declare inputs as regs, outputs as wires
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    // Instantiate TopModule
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;

    // Task to check results
    task check_result;
        input [7:0] exp_s;
        input       exp_ovf;
        begin
            #1; // Allow combinational propagation
            if ((s !== exp_s) || (overflow !== exp_ovf)) begin
                $display("Time %0t: a=%d (%b), b=%d (%b) | Got s=%d (%b), ovf=%b | Expected s=%d (%b), ovf=%b", 
                         $time, $signed(a), a, $signed(b), b, $signed(s), s, overflow, $signed(exp_s), exp_s, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        a = 8'd0;
        b = 8'd0;
        #10;

        // Test Vector 1: Zero + Zero
        a = 8'd0; b = 8'd0;
        check_result(8'd0, 1'b0);

        // Test Vector 2: Positive + Positive (No overflow)
        a = 8'd10; b = 8'd20;
        check_result(8'd30, 1'b0);

        // Test Vector 3: Positive + Positive (Overflow)
        // Max positive (127) + 1 = -128 (Overflow)
        a = 8'h7F; b = 8'h01;
        check_result(8'h80, 1'b1);

        // Test Vector 4: Negative + Negative (No overflow)
        a = -8'd10; b = -8'd20;
        check_result(-8'd30, 1'b0);

        // Test Vector 5: Negative + Negative (Overflow)
        // Min negative (-128) + (-1) = 127 (Overflow)
        a = 8'h80; b = 8'hFF;
        check_result(8'h7F, 1'b1);

        // Test Vector 6: Positive + Negative (Never overflows)
        a = 8'd50; b = -8'd50;
        check_result(8'd0, 1'b0);

        // Test Vector 7: Negative + Positive (Never overflows)
        a = -8'd60; b = 8'd30;
        check_result(-8'd30, 1'b0);

        // Test Vector 8: Boundary check (126 + 1)
        a = 8'd126; b = 8'd1;
        check_result(8'd127, 1'b0);

        // Test Vector 9: Boundary check (-127 + (-1))
        a = -8'd127; b = -8'd1;
        check_result(-8'd128, 1'b0);

        // Test Vector 10: Exhaustive-like bounded loop test
        // Loop through a few combinations
        for (integer i = -32; i < 32; i = i + 11) begin
            for (integer j = -32; j < 32; j = j + 13) begin
                a = i[7:0];
                b = j[7:0];
                // Expected values computed using 9-bit signed arithmetic to detect overflow
                begin
                    reg signed [8:0] full_sum;
                    reg [7:0] exp_s;
                    reg       exp_ovf;

                    full_sum = $signed(a) + $signed(b);
                    exp_s = full_sum[7:0];
                    exp_ovf = (full_sum > 127) || (full_sum < -128);

                    check_result(exp_s, exp_ovf);
                end
            end
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
